// =============================================================================
// CALL EXAMPLES — how a pipeline is called, in every place that shows it
// =============================================================================
//
// One block: a language toggle (JavaScript, TypeScript, Python, HTTP), a Copy
// button and the code, generated by `callExamples.ts` from the address and
// the public parameters with a value each. The API Params page shows it under
// the map editor; the endpoint dialog (the editors' and the Catalog's) shows
// the same block for a source's address. Neither writes its own snippets.

import { CSSProperties, ReactElement, useCallback, useMemo, useState } from 'react';

import { Button, commonStyles, ToggleGroup } from 'shell';

import { buildCallExamples, CALL_EXAMPLE_TABS, type CallExampleTabId, type ICallExampleParam } from './callExamples';

// =============================================================================
// Styles
// =============================================================================

const styles = {
	header: {
		display: 'flex',
		alignItems: 'center',
		justifyContent: 'space-between',
		gap: 12,
		margin: '12px 0 8px',
		flexWrap: 'wrap',
	} as CSSProperties,

	controls: {
		display: 'flex',
		alignItems: 'center',
		gap: 8,
	} as CSSProperties,

	// A long example scrolls inside its block, so it never takes its host's room
	code: {
		...commonStyles.fontMono,
		fontSize: 12,
		lineHeight: 1.5,
		margin: 0,
		padding: 14,
		borderRadius: 7,
		background: 'var(--rr-bg-secondary)',
		border: '1px solid var(--rr-border)',
		whiteSpace: 'pre',
		maxHeight: 220,
		overflow: 'auto',
	} as CSSProperties,
};

// =============================================================================
// Types
// =============================================================================

/** Props for {@link CallExamples}. */
export interface ICallExamplesProps {
	/** The address the examples call (`developerId.pipeId`, optionally `.source`). */
	address: string;
	/** The public parameters, each with the value the example passes. */
	params: ICallExampleParam[];
	/** The server origin for the HTTP example; a placeholder when unknown. */
	host?: string;
	/** A key to show in the HTTP example's Authorization header (one just minted); a placeholder when absent. */
	apiKey?: string;
}

// =============================================================================
// Component
// =============================================================================

/**
 * Renders the call examples of one address.
 *
 * @param props - {@link ICallExamplesProps}.
 * @returns The block: its heading, the language toggle, Copy and the code.
 */
export function CallExamples({ address, params, host, apiKey }: ICallExamplesProps): ReactElement {
	const [tab, setTab] = useState<CallExampleTabId>('javascript');
	const examples = useMemo(() => buildCallExamples({ address, params, host, apiKey }), [address, params, host, apiKey]);
	const copy = useCallback(() => {
		void navigator.clipboard?.writeText(examples[tab]);
	}, [examples, tab]);

	return (
		<div>
			<div style={styles.header}>
				<div style={commonStyles.labelUppercase}>Call examples</div>
				<div style={styles.controls}>
					<ToggleGroup options={CALL_EXAMPLE_TABS.map((t) => ({ id: t.id, label: t.label }))} value={tab} onChange={setTab} small />
					<Button variant="secondary" small onClick={copy} title="Copy to clipboard">
						Copy
					</Button>
				</div>
			</div>
			<pre style={styles.code}>{examples[tab]}</pre>
		</div>
	);
}

export default CallExamples;
